models = {
    "logistic": Pipeline([("pre", pre), ("m", LogisticRegression(C=1.0, max_iter=2000))]),
    "random_forest": Pipeline([("pre", pre), ("m", RandomForestClassifier(n_estimators=200, min_samples_leaf=5, n_jobs=-1, random_state=0))]),
    "grad_boost": Pipeline([("pre", pre), ("m", HistGradientBoostingClassifier(max_iter=200, learning_rate=0.05, random_state=0))]),
}

cv = StratifiedKFold(5, shuffle=True, random_state=0)
scores = {name: cross_validate(m, Xtr, ytr, cv=cv, scoring=["roc_auc", "average_precision"]) for name, m in models.items()}
table = pd.DataFrame({name: {"auc_mean": s["test_roc_auc"].mean(), "auc_sd": s["test_roc_auc"].std(),
                             "ap_mean": s["test_average_precision"].mean(), "ap_sd": s["test_average_precision"].std()}
                      for name, s in scores.items()}).T
print(table.round(4))
